from lib import *
recs=[
R(1904,"Ayam Panggang Oven Manis dan Asam",
"Tidak mengherankan jika Kimberly, ahli diet ginjal DaVita dari Georgia, penggemar ayam goreng ala Selatan. Yang mengejutkan, resepnya yang ramah ginjal untuk Ayam Panggang Oven Manis dan Asam ternyata lebih lezat daripada hidangan tradisionalnya.",
["1/2 cangkir selai aprikot rendah gula","2 sendok makan mustard Dijon","1 sendok makan saus Worcestershire","1/2 sendok teh bubuk bawang putih","3 cangkir cornflakes, dihancurkan kasar","1 sendok teh thyme","1/4 sendok teh lada hitam","6 dada ayam tanpa tulang dan tanpa kulit (1-1/2 pon)"],
["Panaskan oven hingga 350° F.","Olesi tipis loyang berukuran 13” x 9” x 2” dengan semprotan masak antilengket.","Kocok selai aprikot rendah gula, mustard Dijon, saus Worcestershire, dan bubuk bawang putih dalam mangkuk kecil.","Campurkan cornflakes, thyme, dan lada dalam kantong plastik besar (seperti kantong roti atau kantong berzip).","Olesi dada ayam dengan campuran aprikot, lalu balurkan pada campuran remah cornflakes.","Letakkan ayam di dalam loyang yang telah disiapkan.","Panggang selama 35 menit atau hingga suhu bagian dalam mencapai 170° F pada termometer baca-instan.","Sajikan segera, atau dinginkan lalu bawa untuk piknik."],
["PGK non-dialisis: Resep berprotein lebih tinggi ini mungkin cocok untuk diet Anda jika ukuran porsinya disesuaikan untuk mengurangi kandungan proteinnya. Penyesuaian harus didasarkan pada resep protein Anda secara individual. Tanyakan kepada ahli diet Anda jika Anda ragu."],
serving="1 dada ayam"),
R(1906,"Saus Cuka Manis untuk Daging atau Unggas",
"Cobalah resep ramah ginjal Saus Cuka Manis untuk Daging atau Unggas ini. Rendah natrium, fosfor, dan lemak, serta ideal bagi Anda yang menjalani diet diabetes, dialisis, dan PGK non-dialisis.",
["1/4 cangkir cuka sari apel","1/3 cangkir selai persik","1/3 cangkir gula merah","2 sendok makan mentega tanpa garam"],
["Dalam panci kecil, panaskan semua bahan dengan api kecil selama 5 menit. Aduk sesekali.","Sajikan saus panas di atas daging atau unggas."],
["Tambahkan saus Tabasco® untuk versi pedas.","Ganti selai persik dengan selai aprikot."]),
R(1908,"Tart Lemon yang Menyegarkan",
"Ahli diet ginjal DaVita, Janis dari Illinois, menemukan cara memadukan rasa manis dan asam yang sempurna dalam hidangan penutup Tart Lemon yang Menyegarkan ini.",
["1 cangkir tepung terigu serbaguna putih","4 sendok makan gula halus (dibagi)","1/8 sendok teh garam","1/2 cangkir mentega tanpa garam yang dingin","5 ons krim keju, suhu ruang","1/2 cangkir gula pasir","2 butir telur","1/2 cangkir air perasan lemon segar","1 sendok makan parutan kulit lemon","1/2 cangkir krim kocok"],
["Panaskan oven terlebih dahulu hingga 425° F.","Aduk rata tepung, 3 sendok makan gula halus, dan garam. Tambahkan mentega menggunakan alat pemotong adonan atau garpu hingga campuran tampak seperti remah.","Tekan campuran ke dasar dan sisi loyang tart 8” (atau loyang 8” lain dengan dasar yang dapat dilepas, seperti loyang springform). Tusuk dasar kulit tart dengan garpu; tutup lalu simpan di freezer selama 15 menit.","Letakkan loyang tart di atas loyang yang lebih besar dan panggang selama 12 hingga 13 menit. Keluarkan dari oven dan biarkan dingin.","Turunkan suhu oven menjadi 350° F.","Kocok krim keju dalam mangkuk pengaduk hingga halus. Tambahkan gula pasir dan terus kocok hingga halus. Masukkan telur satu per satu dan kocok hingga tercampur rata. Tambahkan air perasan lemon dan kulit lemon, lalu kocok lagi hingga halus.","Tuang isian ke dalam kulit tart yang telah disiapkan dan panggang 25 hingga 30 menit.","Keluarkan dari oven dan biarkan dingin. Tutup tart dan simpan di lemari es selama 1 jam hingga dingin.","Kocok krim kocok bersama sisa 1 sendok makan gula halus hingga terbentuk puncak lembut. Sendokkan krim di sekeliling tepi tart lalu sajikan."],
["Krim kocok juga dikenal sebagai heavy cream. Volumenya menjadi dua kali lipat saat dikocok.","Tanpa krim kocok, lemaknya 19 gram per porsi.","Untuk membuat versi yang ramah diabetes, ganti gula halus dan gula pasir dengan pemanis butiran Splenda®, dan ganti krim kocok dengan satu sendok topping kocok ringan (karbohidrat 18 g, lemak 20 g, kalori 270)."]),
R(1910,"Salsa Mentimun dan Dill",
"Salsa Mentimun dan Dill adalah penyedap rasa untuk salmon dan ikan lain yang ingin Anda beri cita rasa lebih. Juga lezat sebagai saus celup dengan sayuran dan roti yang ramah ginjal.",
["1 buah mentimun ukuran sedang","1 sendok teh air perasan lemon","1/2 cangkir krim asam rendah lemak","1 sendok makan daun dill segar","1 sendok makan bawang merah","1 sendok teh madu","1 sendok teh horseradish siap pakai"],
["Kupas dan potong dadu mentimun. Cincang daun dill dan bawang.","Letakkan mentimun potong dadu dalam mangkuk dan aduk dengan air perasan lemon. Sisihkan.","Campurkan krim asam, daun dill, bawang, madu, dan horseradish dalam mangkuk.","Aduk perlahan mentimun ke dalam campuran krim asam.","Simpan di lemari es hingga siap disajikan."],
["Sajikan dengan Salmon Lumur Madu dan Rempah."]),
R(1913,"Pancit",
"Pada umumnya, makanan Filipina bisa tinggi natrium, kalium, dan fosfor, namun ahli diet dialisis DaVita telah memodifikasi resepnya agar lebih ramah ginjal. Cobalah Pancit dan temukan keunikan California bagian utara.",
["3 siung bawang putih","1/2 cangkir bawang bombai","2 cangkir wortel","4 cangkir kubis","3 batang seledri","2 batang daun bawang","1 sendok makan minyak zaitun","1 cangkir ayam, dimasak","1 cangkir udang, dimasak","1 sendok makan kecap asin rendah natrium","4 cangkir kaldu ayam rendah natrium","16 ons bihun beras (mi beras Asia)","16 ons kacang polong salju beku","1/2 sendok teh lada hitam","1 butir telur, direbus matang","2 buah lemon"],
["Cincang halus bawang putih dan potong dadu bawang bombai. Serut wortel dan kubis, lalu potong seledri secara diagonal. Iris halus daun bawang.","Dalam wajan wok atau penggorengan besar, dengan api sedang, tumis bawang putih dan bawang bombai dalam minyak zaitun hingga layu.","Masukkan ayam, udang, dan kecap asin sambil diaduk. Tambahkan 3 cangkir kaldu ayam dan didihkan.","Masukkan mi menggunakan 2 sendok kayu untuk mengaduknya. Masak selama 15 menit hingga mi tembus pandang. Berhati-hatilah agar mi tidak menjadi lengket. Mungkin perlu menambahkan kaldu (atau air) agar hal itu tidak terjadi.","Tambahkan sayuran dan masak hingga kubis mulai layu.","Pindahkan pancit ke piring saji dan hias dengan irisan telur, daun bawang, dan satu buah lemon yang dipotong menjadi irisan bulan.","Peras air jeruk lemon dari satu buah lemon di atas mi sebelum disajikan. Sajikan segera."],
["Gunakan minyak wijen sebagai pengganti minyak zaitun jika diinginkan.","Anda dapat menggunakan campuran ayam dan udang.","Mi beras, juga dikenal sebagai bihun beras, dapat dibeli di toko bahan makanan Asia mana pun. Merek Excellent® adalah pilihan yang baik.","Serut kubis dan wortel dengan food processor atau beli campuran sayuran serut siap pakai.","Gunakan wok besar atau panci Dutch oven yang sangat besar."]),
R(1915,"Labu Spageti ala Mediterania",
"Labu spageti adalah pengganti pasta yang unik. Serbaguna dan lezat. Resep ini menambahkan warna cantik dari sayuran dan sedikit keju feta.",
["1 buah labu spageti kecil","4 sendok makan minyak zaitun, dibagi","1 buah bawang bombai kecil","1 buah paprika merah ukuran sedang","1 tudung jamur portobello","5 siung besar bawang putih","5 buah tomat ceri","1 cangkir kacang cannellini","1 sendok makan oregano kering","1 sendok makan basil kering","3/4 cangkir kaldu sayuran","1/4 cangkir keju feta yang dihancurkan","1/4 cangkir daun basil untuk hiasan"],
["Panaskan oven hingga 400 derajat F.","Belah dua labu spageti memanjang. Buang bijinya dengan sendok.","Siramkan 1 sendok makan minyak zaitun pada kedua belahan labu, lalu letakkan dengan sisi daging menghadap ke bawah dalam loyang 9×13”. Panggang dalam oven selama 30-40 menit hingga empuk.","Setelah labu spageti dingin, suwir dagingnya dengan garpu, lalu sisihkan.","Masukkan sisa minyak zaitun ke dalam wajan dengan api sedang-besar.","Potong dadu bawang bombai dan masukkan ke wajan. Tumis 3 menit.","Saat bawang bombai dimasak, iris paprika merah dan jamur. Cincang halus bawang putih, belah dua tomat, lalu bilas dan tiriskan kacang cannellini.","Masukkan semua sayuran (kecuali tomat) dan bumbu herba ke dalam wajan bersama bawang bombai. Aduk rata dan masak 5 menit lagi.","Masukkan kaldu, daging labu spageti, kacang, dan tomat ke dalam wajan yang sama. Masak 10 menit lagi.","Setelah matang, tambahkan feta dan basil, lalu sajikan."],
["Sendok es krim sangat berguna untuk mengeluarkan biji labu spageti.","Satu labu spageti kecil menghasilkan sekitar 4 cangkir labu suwir.","Satu tudung jamur portobello beratnya sekitar 3 ons, menghasilkan sekitar 1 cangkir.","Satu bawang bombai kecil menghasilkan 1/2 cangkir cincang kasar, 1/4 cangkir cincang halus.","Ini adalah hidangan berkalium lebih tinggi, tetapi dapat dianggap sebagai makanan lengkap. Hidangan ini dapat dimasukkan ke dalam rencana makan ramah ginjal, dengan mempertimbangkan makanan lain sepanjang hari untuk menyeimbangkan asupan kalium."]),
R(1916,"Dressing Madu Mustard",
"Tambahkan sentuhan manis sekaligus asam pada salad Anda berikutnya dengan resep ramah ginjal Dressing Madu Mustard.",
["1/2 cangkir mayones rendah lemak","1/4 cangkir madu","2 sendok makan mustard kuning","1 sendok makan cuka beras tanpa bumbu"],
["Masukkan semua bahan ke dalam toples; tutup rapat dan kocok hingga tercampur rata.","Simpan di lemari es hingga siap disajikan."],
["Pilih merek mustard dan mayones dengan natrium terendah.","Carilah cuka beras tanpa bumbu dan tambahkan pemanis jika diinginkan. Cuka beras berbumbu sangat tinggi natrium dan gula.","Gunakan mayones biasa jika Anda membutuhkan lebih banyak kalori dalam diet Anda. Kalori meningkat menjadi 154, lemak meningkat menjadi 13 g, dan natrium berkurang menjadi 143 mg."]),
R(1919,"Camilan Cheesecake Lemon",
"Camilan lemon bebas gluten ini adalah hidangan manis yang ringan setelah makan. Dibuat dengan tepung kelapa dan oatmeal.",
["1/2 cangkir tepung kelapa","1/2 cangkir oatmeal biasa","8 ons krim keju","2 sendok makan sirup maple","1/2 sendok teh ekstrak vanila","1/2 sendok teh ekstrak lemon","kulit parut setengah buah lemon","2 sendok makan air perasan lemon"],
["Masukkan tepung kelapa dan oat ke dalam food processor. Proses hingga menjadi bubuk halus, sekitar 1 menit.","Tambahkan bahan lainnya, dan proses hingga halus, sekitar 1 menit.","Dengan sendok kecil pencetak kue atau sekitar satu sendok makan, bentuk sekitar 20-25 bola.","Letakkan bola-bola adonan di atas kertas roti pada loyang kue.","Dinginkan di lemari es selama 2 jam hingga mengeras. Simpan dalam wadah kedap udara di lemari es."],
["Bereksperimenlah dengan rasa. Ekstrak almond atau ekstrak jeruk juga cocok."],
serving="2-3 bola"),
R(1920,"Salad Apel Karamel",
"Anda pasti ingin mengambil sendok dan menyantap Salad Apel Karamel ini. Manis dan renyah, dan yang terbaik, sepenuhnya ramah ginjal!",
["3 cangkir apel Granny Smith","8 ons nanas parut kalengan, dikemas dalam sari buahnya","8 ons topping kocok","1/2 cangkir topping dessert butterscotch","1/3 cangkir kacang tanah tanpa garam","1/4 cangkir keping cokelat butterscotch untuk memanggang"],
["Cuci dan buang bagian tengah apel, tetapi jangan dikupas. Potong apel menjadi dadu sekitar 1″. Cairkan topping kocok.","Campurkan nanas parut (termasuk sarinya) dengan apel potong dadu.","Dalam mangkuk besar terpisah, campurkan topping nonsusu yang telah dicairkan dengan topping dessert rasa butterscotch hingga merata.","Aduk campuran apel/nanas ke dalam campuran topping nonsusu.","Tambahkan keping butterscotch dan kacang tanah tanpa garam ke dalam campuran.","Aduk dan sajikan."],
["Sekitar 2 apel ukuran sedang menghasilkan 3 cangkir.","Buat lebih dulu dan simpan di lemari es, tetapi jangan tambahkan kacang tanah hingga siap disajikan.","Kacang tanah bersifat opsional. Jika digunakan, pastikan memakai kacang tanah tanpa garam; kacang tanah asin akan memengaruhi tekstur salad. 1/3 cangkir kacang tanah menyumbang 32 mg kalium dan 17 mg fosfor per porsi."]),
R(1921,"Ayam Utuh Slow Cooker",
"Ayam Utuh Slow Cooker dapat disajikan dengan salad dan sayuran ramah ginjal untuk makanan yang menyehatkan. Yang terbaik, resep ayam ini adalah dasar bagi berbagai resep lezat lain yang menggunakan ayam.",
["1 ekor ayam utuh seberat 4 pon","1 sendok teh lada hitam","1/2 buah bawang bombai ukuran sedang, dibelah empat","1 batang seledri, dipotong menjadi 3 bagian"],
["Keluarkan jeroan dari rongga ayam dan cuci ayam; buang kulit berlebih dan lemak yang terlihat.","Taburkan sebagian lada di dalam rongga. Masukkan potongan bawang bombai dan seledri ke dalam rongga. Taburkan sisa lada di atas ayam.","Letakkan ayam utuh di dalam slow cooker dengan dada menghadap ke bawah. Masak dengan pengaturan tinggi selama 4 jam, hingga paha dan kaki mudah terlepas dan daging mudah lepas dari tulang.","Buang kulit. Lepaskan daging dari tulang dan bagi menjadi 3 porsi untuk digunakan dalam resep yang disarankan di bawah.","Jika diinginkan, gunakan kaldu dari ayam yang dimasak untuk membuat sup atau bekukan untuk digunakan nanti dalam resep."],
["Ayam seberat empat pon menghasilkan 27 ons daging setelah dikuliti dan dibuang tulangnya (sekitar 4 cangkir).","Jika diinginkan, gunakan kaldu dari ayam yang dimasak untuk membuat sup atau bekukan untuk digunakan nanti dalam resep.","Untuk PGK non-dialisis, sesuaikan ukuran porsi dengan rencana makan Anda atau konsultasikan dengan ahli diet Anda jika Anda menjalani diet rendah protein.","Tortilla Gulung (gunakan ayam sebagai pengganti kalkun)","Salad Buah Ayam","Salad Ayam Dingin dan Renyah","Salad Ayam Kari Lemon","Fajita Ayam","Bungkus Selada Ayam","Bungkus Ayam Renyah","Enchilada Ayam Mudah","Sup Ayam Maroko","Ayam Panggang Berlapis ala Myrna","Salad Ayam Lezat untuk Sandwich"],
serving="3 ons ayam matang"),
R(1923,"Olesan Udang dengan Biskuit",
"Ahli diet DaVita Sara Colman membagikan resep Olesan Udang dengan Biskuit yang ramah ginjal dan dapat Anda sajikan di pesta berikutnya.",
["1/4 cangkir krim keju ringan","2-1/2 ons udang matang tanpa kulit","1 sendok makan saus tomat tanpa tambahan garam","1/4 sendok teh saus pedas Tabasco®","1 sendok teh saus Worcestershire","1/2 sendok teh campuran bumbu herba Mrs. Dash®","24 biskuit matzo mini","1 sendok makan peterseli"],
["Keluarkan krim keju agar melunak.","Cincang halus udang dan aduk ke dalam krim keju.","Aduk saus tomat, saus Tabasco, saus Worcestershire, dan bumbu herba Mrs. Dash®.","Letakkan 1 sendok teh olesan di atas setiap biskuit. Hias dengan peterseli cincang halus."],
["Sajikan dengan batang seledri sebagai pengganti biskuit jika diinginkan."],
serving="3 biskuit, masing-masing dengan 1 sendok teh olesan"),
R(1927,"Apple Crisp",
"Apa yang lebih menenangkan daripada sepotong Apple Crisp untuk camilan atau hidangan penutup yang pasti memuaskan dan sesuai dengan diet ginjal? Ahli diet ginjal, Cristin dari Pennsylvania, memperkenalkan resepnya yang mudah dibuat dan rendah kalium, penuh rasa, serat, dan kebaikan apel.",
["5 buah apel ukuran sedang","1/2 cangkir gula pasir","1-1/4 cangkir tepung terigu serbaguna","1 sendok teh kayu manis","1 cangkir oatmeal","3/4 cangkir gula merah","1/4 sendok teh soda kue","1/4 sendok teh baking powder","1/2 cangkir mentega tanpa garam"],
["Panaskan oven terlebih dahulu hingga 350° F.","Semprot loyang berukuran 9 x 9 inci dengan semprotan masak.","Kupas, buang bagian tengah, dan iris apel.","Campurkan 1/2 cangkir gula pasir, 3 sendok makan tepung, dan 1/2 sendok teh kayu manis. Tambahkan irisan apel dan aduk hingga terbalut rata.","Tuang campuran apel ke dalam loyang yang telah disiapkan.","Dalam mangkuk sedang, campurkan oatmeal, sisa tepung, gula merah, sisa kayu manis, soda kue, dan baking powder. Potong mentega ke dalam campuran ini dengan alat pemotong adonan atau garpu.","Tuang topping di atas apel dan panggang selama 1 jam."],
["Buat hidangan penutup ini ramah diabetes. Ganti gula putih dengan Splenda® butiran dan gula merah dengan campuran gula merah Splenda® untuk mengurangi kalori menjadi 280 dan karbohidrat menjadi 20 gram per porsi.","1 apel ukuran sedang menghasilkan sekitar 1 cangkir setelah dikupas dan dibuang bagian tengahnya."]),
R(1928,"Sari Apel Panas",
"Ingin menikmati sesuatu yang hangat dan beraroma rempah? Resep ramah ginjal Sari Apel Panas mungkin jawabannya. Susan dari Kentucky menyuguhkan minuman rendah gula tetapi kaya rasa. Bersiaplah menikmati racikan untuk cuaca dingin ini.",
["4 cangkir jus apel","4 cangkir jus cranberry rendah gula","2 batang kayu manis","6 butir cengkih utuh","1/2 sendok teh allspice","1 sendok teh bumbu pumpkin pie","1 kantong teh rasa kayu manis"],
["Campurkan semua bahan dalam Crock-Pot®.","Biarkan terseduh selama satu jam atau lebih. Angkat kantong teh.","Sajikan sari apel panas dalam mug kecil."],
["Tambahkan 1/4 cangkir gula merah untuk minuman yang lebih manis."],
serving="4 ons (1/2 cangkir)"),
R(1929,"Muffin Apel Rempah",
"Apel dan saus apel adalah camilan favorit. Mengapa tidak menggabungkan keduanya dengan rempah pai apel untuk membuat Muffin Apel Rempah. Muffin ramah ginjal ini adalah tambahan yang bagus untuk menu camilan Anda.",
["1 cangkir gula","1/3 cangkir minyak canola","2 butir telur besar","1/2 sendok teh kayu manis bubuk","1/2 sendok teh jahe bubuk","1/2 sendok teh cengkih bubuk","1/2 sendok teh pala","1/4 sendok teh garam","1 sendok teh soda kue","1 cangkir saus apel tanpa pemanis","2 cangkir tepung terigu serbaguna","1 buah apel ukuran sedang"],
["Panaskan oven terlebih dahulu hingga 325° F.","Olesi loyang muffin dengan semprotan masak antilengket.","Kocok gula, minyak, dan telur hingga mengembang dan tercampur.","Tambahkan rempah, garam, soda kue, dan saus apel; aduk rata.","Aduk tepung hingga membentuk adonan kental.","Iris atau potong dadu apel menjadi potongan seukuran gigitan (kupas jika diinginkan).","Jika menggunakan irisan, letakkan satu sendok kecil adonan di dasar setiap cetakan muffin, susun irisan apel, lalu tambahkan adonan lagi. Jika menggunakan potongan apel, masukkan ke dalam adonan lalu isi cetakan muffin.","Panggang selama 25-30 menit hingga terasa padat saat disentuh. Keluarkan dari oven dan biarkan dingin."],
["Resep ini menghasilkan 6 muffin besar, 12 muffin sedang, atau 48 muffin mini.","Untuk kandungan karbohidrat yang lebih rendah, ganti gula dengan campuran gula yang berisi setengah gula dan setengah pengganti gula, atau buat muffin mini dan sajikan 2 muffin per porsi (19 gram karbohidrat)."]),
R(1930,"Stuffing Panggang",
"Stuffing Panggang adalah resep ramah ginjal yang menenangkan untuk setiap acara kumpul keluarga di hari libur.",
["1-1/2 cangkir seledri","1 cangkir bawang bombai","1 cangkir mentega tanpa garam","7 lembar roti gandum utuh","8 lembar roti putih","1-1/2 sendok teh sage bubuk","1 sendok teh thyme bubuk","3/4 sendok teh lada","1/2 sendok teh bumbu unggas"],
["Panaskan oven terlebih dahulu hingga 325° F.","Cincang seledri dan bawang bombai. Potong dadu roti.","Lelehkan mentega dalam wajan dengan api sedang lalu tumis seledri dan bawang bombai sambil sering diaduk.","Masukkan 1/3 bagian potongan roti sambil diaduk.","Angkat dari api dan pindahkan campuran roti ke dalam mangkuk yang dalam.","Tambahkan sisa potongan roti, sage, thyme, lada, dan bumbu unggas; aduk rata.","Letakkan stuffing dalam loyang 13” x 9” x 2” yang telah diolesi minyak. Tutup dan panggang selama 30 menit.","Buka penutup dan panggang 15 menit lagi."],
["Campuran stuffing kemasan kotak mengandung lebih dari 500 mg natrium per porsi 1/2 cangkir.","1 cangkir mentega sama dengan 2 batang atau 16 sendok makan. Jika diinginkan, ganti dengan margarin tanpa garam bebas lemak trans."],
serving="1/12 resep"),
]
save(1,recs)
